# owner: platform
"""Tests for snapping spans to a clock step."""

import unittest

from hourglass.rounding import round_spans
from hourglass.models import Span


class RoundSpansTests(unittest.TestCase):
    def test_rounds_start_and_end_to_nearest_step(self):
        spans = [Span(9 * 60 + 2, 17 * 60 + 13)]
        self.assertEqual(round_spans(spans, 15), ["09:00-17:15 (8h 15m)"])

    def test_rounds_down_below_halfway(self):
        self.assertEqual(
            round_spans([Span(9 * 60 + 7, 17 * 60)], 15), ["09:00-17:00 (8h 0m)"]
        )

    def test_rounds_up_from_halfway(self):
        self.assertEqual(
            round_spans([Span(9 * 60 + 8, 17 * 60)], 15), ["09:15-17:00 (7h 45m)"]
        )

    def test_halfway_rounds_up(self):
        self.assertEqual(
            round_spans([Span(9 * 60 + 5, 9 * 60 + 25)], 10),
            ["09:10-09:30 (0h 20m)"],
        )

    def test_step_of_one_leaves_times_alone(self):
        self.assertEqual(round_spans([Span(541, 1000)], 1), ["09:01-16:40 (7h 39m)"])

    def test_step_of_sixty_snaps_to_the_hour(self):
        self.assertEqual(
            round_spans([Span(9 * 60 + 29, 9 * 60 + 30)], 60), ["09:00-10:00 (1h 0m)"]
        )

    def test_end_of_day_is_kept(self):
        self.assertEqual(
            round_spans([Span(23 * 60, 24 * 60)], 15), ["23:00-24:00 (1h 0m)"]
        )

    def test_keeps_order_and_handles_empty_input(self):
        spans = [Span(600, 720), Span(60, 120)]
        self.assertEqual(
            round_spans(spans, 30),
            ["10:00-12:00 (2h 0m)", "01:00-02:00 (1h 0m)"],
        )
        self.assertEqual(round_spans([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 90, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_spans([Span(60, 120)], step)

    def test_span_rounding_to_nothing_raises(self):
        with self.assertRaises(ValueError):
            round_spans([Span(601, 604)], 15)
